<?php
require_once APP_PATH.'/admin-tables.php';
require_once APP_PATH.'/banner-admin.php';
require_once APP_PATH.'/admin-pages.php';
function adminReviewHistory(array $review): void {echo '<h3 class="type-headline-2 mt-24">검토·보완 이력</h3>';if(empty($review['history']))echo '<p class="help">기존 데모 후기 · 이후 변경부터 이력을 기록합니다.</p>';foreach(array_reverse($review['history']??[]) as $h)echo '<div class="list-row"><div class="list-row__body"><strong>'.e(adminStatusLabel($h['status'])).'</strong><p>'.e($h['message']).'</p><small>'.dateLabel($h['at'],'Y.m.d H:i').'</small></div></div>';}
function adminEditForm(string $table,string $id,array $r,array $schema): void {global $repo;
 if($table==='banners'){adminBannerForm($id,$r,$schema);return;}
 $original=$id?$repo->find($table,$id):[];formStart('admin_save',['table'=>$table,'id'=>$id,'expected'=>$id?rowVersion($original):''],'class="admin-panel" data-dirty-form enctype="multipart/form-data"');
 echo hidden('listReturn',adminListUrl($table));echo '<div class="admin-edit-section"><h2 class="type-fixed-heading-2">'.e($schema['title']).' '.($id?'수정':'등록').'</h2><p class="help">저장하면 현재 데모 세션에 반영됩니다. 운영 서버에는 전송하지 않습니다.</p></div>';
 $groups=[];foreach($schema['fields'] as $f=>$config){$group=match(true){in_array($f,['body','description','summary','missions','questions','conditions','help'])=>'내용과 안내',in_array($f,['image','thumbnail'])=>'대표 이미지',str_ends_with($f,'At')=>'일정',in_array($f,['status','publicationStatus','placement','enabled','order','pinned','mode'])=>'게시·노출 설정',default=>'기본 정보'};$groups[$group][$f]=$config;}
 foreach($groups as $group=>$fields){echo '<section class="admin-edit-section"><h3 class="type-headline-1 mb-16">'.e($group).'</h3><div class="admin-form-grid">';foreach($fields as $f=>[$label,$type]){$v=$r[$f]??'';if($type==='datetime-local'&&$v)$v=(new DateTimeImmutable($v))->format('Y-m-d\TH:i');if(is_array($v))$v=implode("\n",$v);echo '<div class="'.($type==='textarea'?'full-span':'').'">';if(is_array($type))echo selectField($f,$label,$type,$v);elseif($type==='category')echo selectField($f,$label,array_column($repo->all('categories'),'name','id'),$v);elseif($type==='boolean')echo selectField($f,$label,['1'=>'사용','0'=>'사용 안 함'],($r[$f]??true)?'1':'0');else echo field($f,$label,$v,$type,in_array($f,['title','name','capacity'])?['required'=>'required']:[]);
 if(in_array($f,['thumbnail','image'])){echo '<div class="admin-image-preview">';if($table==='campaigns')echo campaignImage(array_merge(['brand'=>'체험 분류','categoryId'=>'생활','image'=>'home'],$r,['image'=>oldValue($f,$v)]));elseif($v&&is_file(dirname(APP_PATH).'/public'.$v)&&str_starts_with($v,'/assets/images/'))echo '<div class="media-frame">'.mediaImage($v,'저장된 대표 이미지').'</div>';else echo '<p class="help">이미지가 없으면 제목 중심의 콘텐츠로 표시합니다.</p>';echo '</div>';if($table==='articles')adminUploadControl();else echo '<p class="help">체험 분류별 기존 이미지 프리셋을 선택합니다.</p>';}
 if($table==='articles'&&$f==='body')echo '<p class="help p-16">문단은 빈 줄로 구분하며, 소제목은 ## 으로 시작하세요. 저장된 본문은 사용자 미리보기에서 확인할 수 있습니다.</p>';echo '</div>'; }echo '</div></section>';}
 if($table==='checklist')echo '<p class="paragraph p-16">새 버전은 다음 작성부터 적용됩니다. 과거 일지의 문구·답변은 보존됩니다.</p>';
 echo '<div class="admin-form-footer"><div class="row gap-16"><a class="button button--neutral" href="'.e(adminListUrl($table)).'">취소</a><button class="button">변경사항 저장</button></div></div></form>';
}
